<template>
  <view class="mpb-page" :style="miniProgramNavigationStyle"><view class="mpb-safe" /><view class="mpb-header"><button class="mpb-back" aria-label="返回" @click="backOrHome('/pages/agent/AgentOrdersPage')">‹</button><image class="mpb-logo" :src="loginLogo" mode="aspectFit" /><view class="mpb-header-copy"><text class="mpb-title">客户订单详情</text><text class="mpb-subtitle">客户、金额与归属状态</text></view><text class="mpb-role agent">代理商</text></view><view class="mpb-stack"><view v-if="loading" class="mpb-card mpb-empty"><text class="mpb-empty-title">正在加载客户订单...</text></view><template v-else-if="item"><view class="mpb-hero"><view class="mpb-hero-top"><view><text class="mpb-hero-label">订单金额</text><text class="mpb-hero-value">{{ formatCurrency(orderAmount(item)) }}</text></view><text class="mpb-hero-badge success">{{ statusText(orderStatus(item)) }}</text></view><text class="mpb-hero-copy">{{ orderTitle(item) }}</text></view><view class="mpb-card mpb-list"><view class="mpb-row"><text class="mpb-row-icon">号</text><view class="mpb-row-main"><text class="mpb-row-title">订单编号</text><text class="mpb-row-meta">{{ orderId(item) }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon green">客</text><view class="mpb-row-main"><text class="mpb-row-title">购买客户</text><text class="mpb-row-meta">{{ rowString(item, 'customerName', 'customer', 'email', 'buyerUserId') || '-' }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon orange">时</text><view class="mpb-row-main"><text class="mpb-row-title">创建时间</text><text class="mpb-row-meta">{{ formatDate(rowString(item, 'createdAt', 'paidAt')) }}</text></view></view></view><button v-if="customerId" class="mpb-button" @click="openCustomer">查看客户详情</button></template><view v-else class="mpb-card mpb-empty"><text class="mpb-empty-title">未找到客户订单</text></view></view></view>
</template>
<script setup lang="ts">
import { computed, ref } from "vue"; import { onLoad } from "@dcloudio/uni-app"; import { api } from "../../api/client"; import { asRecord, backOrHome, formatCurrency, formatDate, orderAmount, orderId, orderStatus, orderTitle, rowString, statusText, type AnyRecord } from "../../utils/miniProgramBusiness"; import loginLogo from "../../assets/zhiqiyun-logo-transparent.png";
const id=ref(""); const loading=ref(false); const item=ref<AnyRecord|null>(null); const customerId=computed(()=>rowString(item.value,"customerId","buyerUserId","userId")); async function load(){loading.value=true;try{const payload=asRecord(await api(`/api/v1/channel/orders/${encodeURIComponent(id.value)}`));const detail=asRecord(payload.item);item.value=orderId(detail)?detail:null;}catch(error){uni.showToast({title:error instanceof Error?error.message:"客户订单加载失败",icon:"none"});}finally{loading.value=false;}} function openCustomer(){if(customerId.value)uni.navigateTo({url:`/pages/agent/AgentCustomerDetailPage?id=${encodeURIComponent(customerId.value)}`});} onLoad(options=>{id.value=String(options?.id||"");void load();});
</script>
<style>@import "../../styles/mini-program-business.css";</style>
